{"command":"cd /work/workspace/deliverable && python3 - <<'EOF'
import json
d = json.load(open('comparison.json'))
req = {"asset_sale_buyer_a_as_drafted","stock_sale_buyer_b","asset_sale_counter_allocation","ray_naive_estimate"}
assert set(d) == req
exp = {
 'asset_sale_buyer_a_as_drafted': (1070000,1450000,237300,923200,2176800,3100000,580000),
 'stock_sale_buyer_b':            (0,2430000,0,486000,2364000,2850000,420000),
 'asset_sale_counter_allocation': (420000,2100000,237300,812700,2287300,3100000,580000),
}
for k,(o,c,e,t,n,price,basis) in exp.items():
    v = d[k]
    assert (v['ordinary_income'],v['capital_gain'],v['entity_level_tax'],v['total_tax'],v['net_after_tax']) == (o,c,e,t,n), k
    assert o + c + basis == price, k                       # gain + basis = price
    assert price - t == n, k                               # net identity
    assert round(o*0.37 + c*0.20 + e, 2) == t, k           # rate build-up
assert d['ray_naive_estimate'] == {'net_after_tax': 2480000}
print("comparison.json OK — schema, gain+basis=price, net identity, rate build-up all verified")
EOF"}
